import pathlib,subprocess,re,json
repo=pathlib.Path('/home/bamedeo/kin-wt/build-time');base='38439f5';out=pathlib.Path('/mnt/windows/Users/amedeo/Desktop/gamedev/kin-renderer-header-bench')
paths=subprocess.check_output(['git','diff','--name-only','--','engine','tests'],cwd=repo,text=True).splitlines();checked=[]
def normalized(s):return re.sub(r'\s+','',re.sub(r'^\s*#include[^\n]*\n','',s,flags=re.M))
for path in paths:
 if not path.endswith(('.hpp','.cpp')):continue
 original=subprocess.check_output(['git','show',base+':'+path],cwd=repo,text=True);current=(repo/path).read_text()
 if path.endswith('/backend.hpp'):
  start=original.index('// Mirroring a sprite within its rectangle');end=original.index('// One quad of a draw_sprites()',start);block=original[start:end]
  assert (repo/'engine/include/kin/renderer/flip.hpp').read_text()=='#pragma once\n\n#include <kin/core/types.hpp>\n\nnamespace kin {\n\n'+block+'} // namespace kin\n'
  original=original[:start]+original[end:]
 for declaration in ['class Renderer2D;','struct ShapeMesh;','struct RendererBackendCapabilities;']:
  if current.count(declaration)==original.count(declaration)+1:current=current.replace(declaration,'',1)
 assert normalized(original)==normalized(current),path
 checked.append(path)
result={'base_commit':subprocess.check_output(['git','rev-parse',base],cwd=repo,text=True).strip(),'existing_cpp_files_checked':checked,'fields_signatures_function_bodies_and_assertions_unchanged':True,'flip_definition_and_helpers_moved_byte_for_byte':True};(out/'mechanical-check.json').write_text(json.dumps(result,indent=2)+'\n');print('Verified unchanged fields, signatures, bodies and assertions in',len(checked),'existing C++ files; Flip code moved byte-for-byte.')

